@datatype class Personnel_Mission_Qualification_Operational_Api (
  val id: Art.BridgeId,
  val raw_mission_Id : Art.PortId,
  val mission_facts_Id : Art.PortId,
  val arrival_fact_Id : Art.PortId,
  val mission_invalidity_Id : Art.PortId) extends Personnel_Mission_Qualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var raw_mission: Mining_Threat_Retreat_Supervisor.Raw_Mission_Observation = $

  def get_raw_mission() : Option[Mining_Threat_Retreat_Supervisor.Raw_Mission_Observation] = {
    Contract(
      Ensures(
        Res == Some(raw_mission)
      )
    )
    val value : Option[Mining_Threat_Retreat_Supervisor.Raw_Mission_Observation] = Art.getValue(raw_mission_Id) match {
      case Some(Mining_Threat_Retreat_Supervisor.Raw_Mission_Observation_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port raw_mission.  Expecting 'Mining_Threat_Retreat_Supervisor.Raw_Mission_Observation_Payload' but received ${v}")
        None[Mining_Threat_Retreat_Supervisor.Raw_Mission_Observation]()
      case _ => None[Mining_Threat_Retreat_Supervisor.Raw_Mission_Observation]()
    }
    return value
  }
